INSERT INTO organizer_profiles (id, user_id, organization_name, slug, description, logo, website, phone, city, status, approved_at, approved_by, created_at) VALUES
(1, 2, 'Kosovo Tech Hub', 'kosovo-tech-hub', 'Kosovo Tech Hub builds the country\'s tech community through summits, demo days and meetups. Since 2016 we have connected thousands of developers, founders and investors across the Balkans.', NULL, 'https://kosovotechhub.example', '+383 38 507 504', 'Prishtina', 'approved', NOW() - INTERVAL 216000 MINUTE, 1, NOW() - INTERVAL 230400 MINUTE),
(2, 3, 'Prishtina Live Productions', 'prishtina-live', 'Concert promoter behind the biggest live music nights in Prishtina — from intimate jazz sessions to arena shows.', NULL, 'https://prishtinalive.example', '+383 38 292 814', 'Prishtina', 'approved', NOW() - INTERVAL 216000 MINUTE, 1, NOW() - INTERVAL 230400 MINUTE),
(3, 4, 'Urban Pulse Collective', 'urban-pulse', 'A collective of DJs, designers and party people curating club nights and rooftop sessions.', NULL, 'https://urbanpulse.example', '+383 38 310 638', 'Prishtina', 'approved', NOW() - INTERVAL 216000 MINUTE, 1, NOW() - INTERVAL 230400 MINUTE),
(4, 5, 'LearnLab Academy', 'learnlab-academy', 'Practical workshops and masterclasses in web development, AI, design and digital marketing, taught by working professionals.', NULL, 'https://learnlab.example', '+383 38 496 937', 'Prishtina', 'approved', NOW() - INTERVAL 216000 MINUTE, 1, NOW() - INTERVAL 230400 MINUTE),
(5, 6, 'Run Kosovo', 'run-kosovo', 'Organizers of the Prishtina Marathon and community sport events that get the whole city moving.', NULL, 'https://runkosovo.example', '+383 38 664 228', 'Prishtina', 'approved', NOW() - INTERVAL 216000 MINUTE, 1, NOW() - INTERVAL 230400 MINUTE),
(6, 7, 'Stand Up Prishtina', 'stand-up-prishtina', 'The home of stand-up comedy in Kosovo. New voices, headline acts and the occasional roast.', NULL, 'https://standupprishtina.example', '+383 38 759 222', 'Prishtina', 'approved', NOW() - INTERVAL 216000 MINUTE, 1, NOW() - INTERVAL 230400 MINUTE),
(7, 8, 'Dukagjini Culture Lab', 'dukagjini-culture-lab', 'Independent cultural organization from Peja producing film screenings, exhibitions and heritage tours.', NULL, NULL, '+383 38 955 353', 'Peja', 'pending', NULL, NULL, NOW() - INTERVAL 2880 MINUTE);
INSERT INTO events (id, organizer_id, category_id, title, slug, short_description, description, cover_image, venue_name, address, city, country, latitude, longitude, starts_at, ends_at, status, is_featured, views, approved_at, cancelled_at, created_at) VALUES
(1, 1, 3, 'Kosovo Tech Summit 2026', 'kosovo-tech-summit-2026', 'The largest technology conference in Kosovo — 40 speakers, 3 stages and 1,000+ builders under one roof.', 'Kosovo Tech Summit brings together developers, founders, investors and product people from across the Balkans and the diaspora for one full day of talks, workshops and networking.
