-- =====================================================================
--  LemboEvents — database schema + demo data
--  Import this file in phpMyAdmin (Import tab) or run:
--     mysql -u root < database/schema.sql
--  It creates the `lemboevents` database from scratch.
--  Demo dates are relative to the import date (NOW()), so the platform
--  always looks alive: upcoming events are in the future, past events
--  have reviews and check-ins.
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP DATABASE IF EXISTS lemboevents;
CREATE DATABASE lemboevents CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE lemboevents;

-- ---------------------------------------------------------------------
-- Users & profiles
-- ---------------------------------------------------------------------
CREATE TABLE users (
    id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    role            ENUM('attendee','organizer','admin') NOT NULL DEFAULT 'attendee',
    first_name      VARCHAR(60)  NOT NULL,
    last_name       VARCHAR(60)  NOT NULL,
    email           VARCHAR(190) NOT NULL,
    password_hash   VARCHAR(255) NOT NULL,
    phone           VARCHAR(30)  NULL,
    city            VARCHAR(80)  NULL,
    avatar          VARCHAR(255) NULL,
    status          ENUM('active','suspended') NOT NULL DEFAULT 'active',
    suspended_reason VARCHAR(255) NULL,
    last_login_at   DATETIME NULL,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_users_email (email),
    KEY idx_users_role_status (role, status)
) ENGINE=InnoDB;

CREATE TABLE attendee_profiles (
    user_id         INT UNSIGNED PRIMARY KEY,
    bio             VARCHAR(500) NULL,
    date_of_birth   DATE NULL,
    newsletter      TINYINT(1) NOT NULL DEFAULT 1,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT fk_attendee_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE organizer_profiles (
    id                INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id           INT UNSIGNED NOT NULL,
    organization_name VARCHAR(120) NOT NULL,
    slug              VARCHAR(140) NOT NULL,
    description       TEXT NULL,
    logo              VARCHAR(255) NULL,
    website           VARCHAR(190) NULL,
    phone             VARCHAR(30)  NULL,
    city              VARCHAR(80)  NULL,
    status            ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
    rejection_reason  VARCHAR(255) NULL,
    approved_at       DATETIME NULL,
    approved_by       INT UNSIGNED NULL,
    created_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_org_user (user_id),
    UNIQUE KEY uq_org_slug (slug),
    KEY idx_org_status (status),
    CONSTRAINT fk_org_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_org_approver FOREIGN KEY (approved_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- Catalog
-- ---------------------------------------------------------------------
CREATE TABLE categories (
    id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name         VARCHAR(60)  NOT NULL,
    slug         VARCHAR(80)  NOT NULL,
    icon         VARCHAR(40)  NOT NULL DEFAULT 'spark',
    color        CHAR(7)      NOT NULL DEFAULT '#FF4D2E',
    description  VARCHAR(255) NULL,
    sort_order   SMALLINT     NOT NULL DEFAULT 0,
    is_active    TINYINT(1)   NOT NULL DEFAULT 1,
    created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_categories_slug (slug),
    UNIQUE KEY uq_categories_name (name)
) ENGINE=InnoDB;

CREATE TABLE events (
    id                INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    organizer_id      INT UNSIGNED NOT NULL,
    category_id       INT UNSIGNED NOT NULL,
    title             VARCHAR(150) NOT NULL,
    slug              VARCHAR(170) NOT NULL,
    short_description VARCHAR(255) NOT NULL,
    description       TEXT NOT NULL,
    cover_image       VARCHAR(255) NULL,
    venue_name        VARCHAR(120) NOT NULL,
    address           VARCHAR(190) NULL,
    city              VARCHAR(80)  NOT NULL,
    country           VARCHAR(80)  NOT NULL DEFAULT 'Kosovo',
    latitude          DECIMAL(9,6) NULL,
    longitude         DECIMAL(9,6) NULL,
    starts_at         DATETIME NOT NULL,
    ends_at           DATETIME NOT NULL,
    status            ENUM('draft','pending','published','rejected','cancelled') NOT NULL DEFAULT 'draft',
    is_featured       TINYINT(1) NOT NULL DEFAULT 0,
    rejection_reason  VARCHAR(255) NULL,
    views             INT UNSIGNED NOT NULL DEFAULT 0,
    approved_at       DATETIME NULL,
    cancelled_at      DATETIME NULL,
    created_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_events_slug (slug),
    KEY idx_events_status_start (status, starts_at),
    KEY idx_events_city (city),
    KEY idx_events_category (category_id),
    KEY idx_events_organizer (organizer_id),
    CONSTRAINT fk_events_org FOREIGN KEY (organizer_id) REFERENCES organizer_profiles(id) ON DELETE CASCADE,
    CONSTRAINT fk_events_category FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE event_images (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    event_id    INT UNSIGNED NOT NULL,
    path        VARCHAR(255) NOT NULL,
    caption     VARCHAR(150) NULL,
    sort_order  SMALLINT NOT NULL DEFAULT 0,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_event_images_event (event_id),
    CONSTRAINT fk_event_images_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- quantity_sold is a counter maintained inside the booking transaction
-- (UPDATE ... WHERE quantity - quantity_sold >= n) so overbooking is impossible.
CREATE TABLE ticket_types (
    id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    event_id        INT UNSIGNED NOT NULL,
    name            VARCHAR(80)  NOT NULL,
    description     VARCHAR(255) NULL,
    price           DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    quantity        INT UNSIGNED NOT NULL,
    quantity_sold   INT UNSIGNED NOT NULL DEFAULT 0,
    max_per_order   TINYINT UNSIGNED NOT NULL DEFAULT 10,
    sale_starts_at  DATETIME NULL,
    sale_ends_at    DATETIME NULL,
    sort_order      SMALLINT NOT NULL DEFAULT 0,
    is_active       TINYINT(1) NOT NULL DEFAULT 1,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY idx_ticket_types_event (event_id),
    CONSTRAINT fk_ticket_types_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,
    CONSTRAINT chk_ticket_types_sold CHECK (quantity_sold <= quantity)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- Bookings & tickets
-- ---------------------------------------------------------------------
CREATE TABLE bookings (
    id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    reference       VARCHAR(20) NOT NULL,
    user_id         INT UNSIGNED NOT NULL,
    event_id        INT UNSIGNED NOT NULL,
    status          ENUM('confirmed','cancelled','refunded') NOT NULL DEFAULT 'confirmed',
    subtotal        DECIMAL(10,2) NOT NULL,
    service_fee     DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    total           DECIMAL(10,2) NOT NULL,
    currency        CHAR(3) NOT NULL DEFAULT 'EUR',
    customer_name   VARCHAR(120) NOT NULL,
    customer_email  VARCHAR(190) NOT NULL,
    customer_phone  VARCHAR(30)  NULL,
    payment_method  ENUM('card','free') NOT NULL DEFAULT 'card',
    payment_last4   CHAR(4) NULL,
    paid_at         DATETIME NULL,
    cancelled_at    DATETIME NULL,
    cancel_reason   VARCHAR(255) NULL,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_bookings_reference (reference),
    KEY idx_bookings_user (user_id),
    KEY idx_bookings_event_status (event_id, status),
    KEY idx_bookings_created (created_at),
    CONSTRAINT fk_bookings_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT,
    CONSTRAINT fk_bookings_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE booking_items (
    id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    booking_id      INT UNSIGNED NOT NULL,
    ticket_type_id  INT UNSIGNED NOT NULL,
    quantity        SMALLINT UNSIGNED NOT NULL,
    unit_price      DECIMAL(10,2) NOT NULL,
    line_total      DECIMAL(10,2) NOT NULL,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_booking_items (booking_id, ticket_type_id),
    KEY idx_booking_items_type (ticket_type_id),
    CONSTRAINT fk_items_booking FOREIGN KEY (booking_id) REFERENCES bookings(id) ON DELETE CASCADE,
    CONSTRAINT fk_items_type FOREIGN KEY (ticket_type_id) REFERENCES ticket_types(id) ON DELETE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE tickets (
    id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    booking_item_id INT UNSIGNED NOT NULL,
    code            CHAR(16) NOT NULL,
    attendee_name   VARCHAR(120) NOT NULL,
    status          ENUM('valid','checked_in','cancelled') NOT NULL DEFAULT 'valid',
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_tickets_code (code),
    KEY idx_tickets_item (booking_item_id),
    KEY idx_tickets_status (status),
    CONSTRAINT fk_tickets_item FOREIGN KEY (booking_item_id) REFERENCES booking_items(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- One row per successful check-in; the UNIQUE key makes a double check-in impossible
-- even if two scanners hit the same ticket at the same moment.
CREATE TABLE check_ins (
    id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    ticket_id       INT UNSIGNED NOT NULL,
    checked_in_by   INT UNSIGNED NULL,
    method          ENUM('qr','manual') NOT NULL DEFAULT 'qr',
    checked_in_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_check_ins_ticket (ticket_id),
    KEY idx_check_ins_time (checked_in_at),
    CONSTRAINT fk_check_ins_ticket FOREIGN KEY (ticket_id) REFERENCES tickets(id) ON DELETE CASCADE,
    CONSTRAINT fk_check_ins_user FOREIGN KEY (checked_in_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- Engagement
-- ---------------------------------------------------------------------
CREATE TABLE reviews (
    id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    event_id        INT UNSIGNED NOT NULL,
    user_id         INT UNSIGNED NOT NULL,
    booking_id      INT UNSIGNED NOT NULL,
    rating          TINYINT UNSIGNED NOT NULL,
    title           VARCHAR(120) NULL,
    comment         TEXT NOT NULL,
    status          ENUM('visible','hidden') NOT NULL DEFAULT 'visible',
    organizer_reply TEXT NULL,
    replied_at      DATETIME NULL,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_reviews_user_event (user_id, event_id),
    UNIQUE KEY uq_reviews_booking (booking_id),
    KEY idx_reviews_event_status (event_id, status),
    CONSTRAINT fk_reviews_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,
    CONSTRAINT fk_reviews_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_reviews_booking FOREIGN KEY (booking_id) REFERENCES bookings(id) ON DELETE CASCADE,
    CONSTRAINT chk_reviews_rating CHECK (rating BETWEEN 1 AND 5)
) ENGINE=InnoDB;

CREATE TABLE favorites (
    user_id     INT UNSIGNED NOT NULL,
    event_id    INT UNSIGNED NOT NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, event_id),
    KEY idx_favorites_event (event_id),
    CONSTRAINT fk_favorites_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_favorites_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE notifications (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id     INT UNSIGNED NOT NULL,
    type        VARCHAR(40)  NOT NULL,
    title       VARCHAR(150) NOT NULL,
    message     VARCHAR(500) NOT NULL,
    link        VARCHAR(255) NULL,
    is_read     TINYINT(1) NOT NULL DEFAULT 0,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_notifications_user_read (user_id, is_read, created_at),
    CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE reports (
    id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    reporter_id  INT UNSIGNED NULL,
    target_type  ENUM('event','review','organizer') NOT NULL,
    target_id    INT UNSIGNED NOT NULL,
    reason       ENUM('spam','inappropriate','fraud','misleading','other') NOT NULL,
    details      VARCHAR(1000) NULL,
    status       ENUM('open','resolved','dismissed') NOT NULL DEFAULT 'open',
    admin_note   VARCHAR(255) NULL,
    resolved_by  INT UNSIGNED NULL,
    resolved_at  DATETIME NULL,
    created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY idx_reports_status (status),
    KEY idx_reports_target (target_type, target_id),
    CONSTRAINT fk_reports_reporter FOREIGN KEY (reporter_id) REFERENCES users(id) ON DELETE SET NULL,
    CONSTRAINT fk_reports_resolver FOREIGN KEY (resolved_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- System
-- ---------------------------------------------------------------------
CREATE TABLE activity_logs (
    id           BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id      INT UNSIGNED NULL,
    action       VARCHAR(60)  NOT NULL,
    entity_type  VARCHAR(40)  NULL,
    entity_id    INT UNSIGNED NULL,
    description  VARCHAR(255) NOT NULL,
    ip_address   VARCHAR(45)  NULL,
    created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_activity_created (created_at),
    KEY idx_activity_user (user_id),
    CONSTRAINT fk_activity_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE password_resets (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id     INT UNSIGNED NOT NULL,
    token_hash  CHAR(64) NOT NULL,
    expires_at  DATETIME NOT NULL,
    used_at     DATETIME NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_password_resets_token (token_hash),
    KEY idx_password_resets_user (user_id),
    CONSTRAINT fk_password_resets_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE login_attempts (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    email       VARCHAR(190) NOT NULL,
    ip_address  VARCHAR(45)  NOT NULL,
    success     TINYINT(1) NOT NULL DEFAULT 0,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_login_attempts_lookup (email, ip_address, created_at)
) ENGINE=InnoDB;

CREATE TABLE newsletter_subscribers (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    email       VARCHAR(190) NOT NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_newsletter_email (email)
) ENGINE=InnoDB;

-- LemboBot conversation log (also used for per-user / per-IP rate limiting)
CREATE TABLE chatbot_messages (
    id          BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id     INT UNSIGNED NULL,
    session_id  VARCHAR(128) NOT NULL,
    sender      ENUM('user','bot') NOT NULL,
    message     TEXT NOT NULL,
    source      ENUM('user','ai','fallback','system') NOT NULL DEFAULT 'user',
    ip_address  VARCHAR(45) NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_chatbot_user (user_id, created_at),
    KEY idx_chatbot_session (session_id, created_at),
    KEY idx_chatbot_ip (ip_address, created_at),
    CONSTRAINT fk_chatbot_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

SET FOREIGN_KEY_CHECKS = 1;

